type Role = "user" | "admin";
type Screen = "login" | "profile" | Role;
type Category = CivicCategory;
type Status = "Received" | "Verified" | "Assigned" | "In progress" | "Resolved";
type Report = {
  id: string; category: Category; area: string; note: string; status: Status;
  time: string; priority: "High" | "Medium" | "Low"; reply: string; reporter: string; contact?: UserContactProfile;
};
type Prediction = { area: string; score: number; category: Category; reason: string; action: string };
type Dispatch = { id: string; department: CivicDepartment; category: Category; area: string; source: string; instruction: string; time: string };
type WeatherTheme = "clear" | "cloudy" | "rain" | "thunderstorm";
type LiveWeather = { temperature: number | null; apparent: number | null; precipitation: number; rainProbability: number; wind: number; label: string; theme: WeatherTheme; updated: string; live: boolean };

