  "Gamma 2": { x: 68, y: 45 }, "Delta 1": { x: 52, y: 48 }, "Delta 2": { x: 55, y: 48 },
  "Surajpur": { x: 62, y: 60 }, "Kasna": { x: 55, y: 75 }, "Ecotech 1": { x: 35, y: 82 },
  "Ecotech 2": { x: 38, y: 82 }, "Ecotech 3": { x: 41, y: 82 }, "Sector 10": { x: 45, y: 70 },
  "Sector 12": { x: 48, y: 63 }, "Sector 16C": { x: 28, y: 38 }, "Sector 36": { x: 68, y: 53 },
